package search

// BinarySearch returns the index of target in sorted slice, or -1 if not found.
func BinarySearch(nums []int, target int) int {
	lo, hi := 0, len(nums)-1
	for lo < hi { // bug: should be lo <= hi
		mid := (lo + hi) / 2 // bug: safe but acceptable; real bug is loop condition
		if nums[mid] == target {
			return mid
		} else if nums[mid] < target {
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}
	return -1
}

// FirstOccurrence returns the index of the first occurrence of target, or -1.
func FirstOccurrence(nums []int, target int) int {
	lo, hi := 0, len(nums)-1
	result := -1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		if nums[mid] == target {
			return mid // bug: should set result=mid and continue searching left (hi=mid-1)
		} else if nums[mid] < target {
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}
	return result
}

