package search

import "testing"

func TestBinarySearch(t *testing.T) {
	nums := []int{1, 3, 5, 7, 9, 11}
	if got := BinarySearch(nums, 7); got != 3 {
		t.Errorf("BinarySearch(7) = %d, want 3", got)
	}
	if got := BinarySearch(nums, 1); got != 0 {
		t.Errorf("BinarySearch(1) = %d, want 0", got)
	}
	if got := BinarySearch(nums, 11); got != 5 {
		t.Errorf("BinarySearch(11) = %d, want 5", got)
	}
	if got := BinarySearch(nums, 4); got != -1 {
		t.Errorf("BinarySearch(4) = %d, want -1", got)
	}
}

func TestFirstOccurrence(t *testing.T) {
	nums := []int{1, 2, 2, 2, 3, 4}
	if got := FirstOccurrence(nums, 2); got != 1 {
		t.Errorf("FirstOccurrence(2) = %d, want 1", got)
	}
	if got := FirstOccurrence(nums, 1); got != 0 {
		t.Errorf("FirstOccurrence(1) = %d, want 0", got)
	}
	if got := FirstOccurrence(nums, 5); got != -1 {
		t.Errorf("FirstOccurrence(5) = %d, want -1", got)
	}
}
